import json

class Player:
    def __init__(self, name: str, team: int):
        self.name = name
        self.team = team

    def __str__(self) -> str:
        return f"{self.name} ({self.team})"

class Game:
    def __init__(self, players: list[Player], teams: int) -> None:
        self.players = players
        self.teams = teams

    def play(self):
        """Simulate a game."""
        moves = self.load_moves()
        self.display_moves(moves)

    def load_moves(self):
        """Load the game moves from a JSON file."""
        with open("movements.json") as f:
            data = json.load(f)
        return data['moves']

    def display_moves(self, moves: list[str]) -> None:
        """Display the game moves."""
        for move in moves:
            print(move)

def main():
    # Create players for both teams.
    player_one = Player("Bats","1")
    player_two = Player("Deep","2")

    # Create two teams
    teams = {"1": [player_one],"2": [player_two]}

    # Create a game
    chess = Game(players=teams, teams=len(teams))
    chess.play()

